def fg_segments(grid, color):
    # Group same-sum cells into maximal connected intervals in v along one diagonal.
    groups={}
    for r,row in enumerate(grid):
        for c,x in enumerate(row):
            if x==color:
                u=r+c; v=r-c
                groups.setdefault(u,[]).append(v)
    segs=[]
    for u,vs in groups.items():
        vs=sorted(vs)
        # a diagonal segment progresses in v by 2; split at missing adjacent diagonal cells
        chunk=[vs[0]]
        for v in vs[1:]:
            if v==chunk[-1]+2: chunk.append(v)
            else:
                segs.append((u,min(chunk),max(chunk)))
                chunk=[v]
        segs.append((u,min(chunk),max(chunk)))
    return sorted(segs)

def fill_per_v(grid,color,bg=8,fill=2):
    segs=fg_segments(grid,color)
    out=[row[:] for row in grid]
    for r in range(len(grid)):
      for c in range(len(grid[0])):
        u=r+c; v=r-c
        active=sorted(set(us for us,lo,hi in segs if lo<=v<=hi))
        for a,b in zip(active,active[1:]):
          if a<u<b:
            out[r][c]=fill
            break
    return out,segs

